// Lógica do nó "Decidir" do fluxo "eLabFTW – Numeração das evidências".
// Função pura: recebe as Evidências completas (GET /items/{id}), os usuários e os avisos já enviados;
// devolve as alterações a fazer e os avisos a mandar (com o pedido de e-mail para o subfluxo).

const DIA = 24 * 3600e3;
const NUMERO = /^E(\d{2,})(?!\d)/;

function dataElab(s, fuso) {
  if (!s) return null;
  const d = new Date(`${String(s).replace(' ', 'T')}${fuso}`);
  return Number.isNaN(d.getTime()) ? null : d;
}

function metadadosDe(x) {
  let m = x.metadata_decoded || x.metadata;
  if (typeof m === 'string') {
    try { m = JSON.parse(m); } catch (e) { m = null; }
  }
  return m && typeof m === 'object' ? m : null;
}

function numeroDe(titulo) {
  const r = NUMERO.exec(String(titulo || '').trim());
  return r ? Number(r[1]) : null;
}

function fichasDe(x, cfg) {
  const ids = new Map();
  for (const l of [...(x.items_links || []), ...(x.related_items_links || [])]) {
    if (l && l.category_title === cfg.categoriaFicha) ids.set(String(l.entityid), l.title || '');
  }
  return [...ids].map(([id, titulo]) => ({ id: Number(id), titulo }));
}

const MOTIVOS = {
  'sem-ficha': {
    assunto: 'ligue a evidência à ficha do projeto',
    texto: 'A evidência não está ligada a nenhuma ficha de projeto, por isso não pôde ser numerada. Abra a evidência e, na seção Links, ligue-a à ficha do projeto. O número sai na próxima conferência.',
  },
  'varias-fichas': {
    assunto: 'evidência ligada a mais de um projeto',
    texto: 'A evidência está ligada a mais de uma ficha de projeto, e a numeração é por projeto. Deixe só a ligação com o projeto ao qual ela pertence. O número sai na próxima conferência.',
  },
  bloqueada: {
    assunto: 'evidência bloqueada sem número',
    texto: 'A evidência está bloqueada para edição e não pôde ser numerada. Desbloqueie-a ou ponha o número no início do título (formato E07 · descrição).',
  },
  duplicado: {
    assunto: 'número de evidência repetido no projeto',
    texto: 'Há mais de uma evidência com o mesmo número neste projeto. O fluxo não corrige números já dados: renumere uma delas à mão e atualize as citações.',
  },
};

function decidirEvidencias({ evidencias, usuarios, avisos, hoje, cfg }) {
  const usuario = new Map(usuarios.filter((u) => u && u.userid !== undefined).map((u) => [String(u.userid), u]));
  const avisado = new Map(avisos.filter((a) => a && a.chave).map((a) => [String(a.chave), a]));
  const testador = usuario.get(String(cfg.usuarioTesteId));
  const fichasTeste = new Set((cfg.fichasTeste || []).map(Number));
  const urlDe = (id) => `${cfg.urlPublica}/database.php?mode=view&id=${id}`;
  const saida = [];
  const simulados = [];

  const evs = evidencias
    .filter((x) => x && x.id !== undefined && x.category_title === cfg.categoriaEvidencia)
    .map((x) => ({ x, fichas: fichasDe(x, cfg), numero: numeroDe(x.title) }))
    .sort((a, b) => Number(a.x.id) - Number(b.x.id));

  // maior número e números repetidos por projeto
  const maior = new Map();
  const vistos = new Map();
  for (const e of evs) {
    if (e.numero === null || e.fichas.length !== 1) continue;
    const f = e.fichas[0].id;
    maior.set(f, Math.max(maior.get(f) || 0, e.numero));
    const k = `${f}:${e.numero}`;
    vistos.set(k, [...(vistos.get(k) || []), e]);
  }

  function destinatario(userid) {
    const dono = usuario.get(String(userid));
    const real = dono && dono.email ? dono.email : '';
    if (cfg.modoTeste && !(testador && testador.email)) {
      throw new Error(`Modo de teste: usuário ${cfg.usuarioTesteId} sem e-mail legível pela API; nada foi feito.`);
    }
    return { dono, real, para: cfg.modoTeste ? testador.email : real };
  }

  function email({ userid, assunto, titulo, blocos, url, rotulo }) {
    const { dono, real, para } = destinatario(userid);
    const nome = (dono && dono.fullname) || 'pesquisador(a)';
    const b = [{ tipo: 'paragrafo', texto: `Olá, ${nome}.` }, ...blocos];
    if (cfg.modoTeste) b.push({ tipo: 'aviso', tom: 'atencao', texto: `Modo de teste: este e-mail iria para ${nome}${real ? ` (${real})` : ' (sem e-mail)'}.` });
    return {
      para,
      nomeRemetente: 'PD&I Modal',
      responderPara: 'pesquisa@modal.org.br',
      assunto: `${cfg.modoTeste ? '[TESTE] ' : ''}eLabFTW: ${assunto}`,
      etiqueta: 'eLabFTW · Evidências',
      titulo,
      blocos: b,
      acaoRotulo: rotulo,
      acaoUrl: url,
      rodape: 'Conferência automática das evidências do eLabFTW do Modal (Diretrizes, seção 6). Dúvidas: pesquisa@modal.org.br.',
    };
  }

  function aviso(chave, motivo, userid, x, extra = []) {
    const anterior = avisado.get(chave);
    if (anterior && anterior.ultimo_aviso && hoje - new Date(anterior.ultimo_aviso) < cfg.repetirDias * DIA) return;
    const m = MOTIVOS[motivo];
    const pedido = email({
      userid,
      assunto: m.assunto,
      titulo: `Evidência "${x.title}": ${m.assunto}`,
      blocos: [{ tipo: 'paragrafo', texto: m.texto }, ...extra],
      url: urlDe(x.id),
      rotulo: 'Abrir no eLabFTW',
    });
    const registro = { chave, evidencia_id: Number(x.id), motivo, ultimo_aviso: hoje.toISOString() };
    saida.push(pedido.para ? { acao: 'avisar', ...registro, ...pedido } : { acao: 'sem-destinatario', ...registro });
  }

  // números repetidos: um aviso por projeto e número, ao dono da evidência mais antiga
  for (const [k, lista] of vistos) {
    if (lista.length < 2) continue;
    const [f, n] = k.split(':');
    aviso(`p${f}:E${n}:duplicado`, 'duplicado', lista[0].x.userid, lista[0].x, [
      { tipo: 'lista', itens: lista.map((e) => ({ texto: e.x.title, url: urlDe(e.x.id) })) },
    ]);
  }

  for (const e of evs) {
    const { x } = e;
    const quieto = [x.created_at, x.modified_at].map((s) => dataElab(s, cfg.fuso)).filter(Boolean);
    if (quieto.length === 0 || quieto.some((d) => hoje - d < cfg.minutosParado * 60e3)) continue;

    const meta = metadadosDe(x);
    const campoSigilo = meta && meta.extra_fields && meta.extra_fields[cfg.campoSigilo];
    const semSigilo = Boolean(campoSigilo) && !String(campoSigilo.value || '').trim();
    const precisaNumero = e.numero === null;
    if (!precisaNumero && !semSigilo) continue;

    if (precisaNumero && e.fichas.length !== 1) {
      aviso(`e${x.id}:${e.fichas.length ? 'varias-fichas' : 'sem-ficha'}`, e.fichas.length ? 'varias-fichas' : 'sem-ficha', x.userid, x);
      continue;
    }
    if (Number(x.locked) === 1) {
      if (precisaNumero) aviso(`e${x.id}:bloqueada`, 'bloqueada', x.userid, x);
      continue;
    }

    const ficha = e.fichas[0] || null;
    const patch = {};
    const mudancas = [];
    let titulo = x.title;
    if (precisaNumero) {
      const n = (maior.get(ficha.id) || 0) + 1;
      maior.set(ficha.id, n);
      titulo = `E${String(n).padStart(2, '0')} · ${String(x.title || '').trim()}`;
      patch.title = titulo;
      mudancas.push({ rotulo: 'Número', valor: titulo.split(' · ')[0] });
    }
    if (semSigilo) {
      const novo = JSON.parse(JSON.stringify(meta));
      novo.extra_fields[cfg.campoSigilo].value = cfg.sigiloPadrao;
      patch.metadata = JSON.stringify(novo);
      mudancas.push({ rotulo: 'Sigilo', valor: `${cfg.sigiloPadrao} (estava vazio; ajuste se não for o caso)` });
    }

    const resumo = { evidencia_id: Number(x.id), titulo_antes: x.title, titulo_depois: titulo, ficha_id: ficha ? ficha.id : null, mudancas };
    if (cfg.modoTeste && !(ficha && fichasTeste.has(ficha.id))) {
      const chave = `sim:e${x.id}`;
      const anterior = avisado.get(chave);
      if (anterior && anterior.ultimo_aviso && hoje - new Date(anterior.ultimo_aviso) < cfg.repetirDias * DIA) continue;
      simulados.push(resumo);
      saida.push({ acao: 'memorizar', chave, evidencia_id: Number(x.id), motivo: 'simulado', ultimo_aviso: hoje.toISOString() });
      continue;
    }
    const pedido = email({
        userid: x.userid,
        assunto: `evidência ${precisaNumero ? `numerada como ${titulo.split(' · ')[0]}` : 'com sigilo preenchido'}`,
        titulo: precisaNumero ? `Sua evidência recebeu o número ${titulo.split(' · ')[0]}` : 'O sigilo da sua evidência foi preenchido',
        blocos: [
          { tipo: 'paragrafo', texto: precisaNumero
            ? `A evidência "${x.title}" foi numerada na sequência do projeto. Cite-a pelo número no caderno e nos relatórios.`
            : `A evidência "${x.title}" estava sem sigilo e recebeu o padrão das Diretrizes.` },
          { tipo: 'campos', itens: [
            ...(ficha ? [{ rotulo: 'Projeto', valor: ficha.titulo, url: urlDe(ficha.id) }] : []),
            { rotulo: 'Evidência', valor: titulo },
            ...mudancas,
          ] },
        ],
        url: urlDe(x.id),
        rotulo: 'Abrir a evidência',
      });
    saida.push({ acao: 'alterar', ...resumo, patch, enviar: Boolean(pedido.para), ...pedido });
  }

  if (simulados.length && testador && testador.email) {
    saida.push({
      acao: 'relatar',
      para: testador.email,
      nomeRemetente: 'PD&I Modal',
      assunto: `[TESTE] eLabFTW: ${simulados.length} alteração(ões) de evidência simulada(s)`,
      etiqueta: 'eLabFTW · Evidências',
      titulo: 'Alterações que o fluxo faria fora das fichas de teste',
      blocos: [
        { tipo: 'paragrafo', texto: 'Modo de teste: nada foi alterado nestas evidências.' },
        { tipo: 'lista', itens: simulados.map((s) => ({ texto: `${s.titulo_antes} → ${s.mudancas.map((m) => `${m.rotulo}: ${m.valor}`).join('; ')}`, url: urlDe(s.evidencia_id) })) },
      ],
      rodape: 'Relatório do modo de teste do fluxo de numeração das evidências.',
    });
  }
  return saida;
}


const dados = (nome) => $(nome).all().map((i) => i.json);
const saida = decidirEvidencias({
  evidencias: dados('Ler evidência completa'),
  usuarios: dados('Ler usuários'),
  avisos: dados('Ler avisos anteriores'),
  hoje: new Date(),
  cfg: $('Configuração').first().json,
});
return saida.map((json) => ({ json }));

